#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU.
# Every catalog SKU appears in the report (HANDOFF.md), even with no
# movements or a zero net for the day.
{
    awk '{ net[$1] += ($2 == "receipt" ? $3 : -$3) }
         END { for (sku in net) print sku, net[sku] }' movements.log
    # Catalog SKUs that may have no movements on a given day.
    awk '{print $1, "0"}' <<'EOF'
SKU-9
EOF
} | sort > stock.txt
